const entity = this.entity;
const columnConfig = this.getDisplayColumnConfig();

const entityAction = this.utilityService.buildEntityAction(entity, "SelectAll");
return this.entityCacheService.getAll(entityAction, entity, page, limit, columnConfig, query);

// Assumes this logic is inside a function where entityType, entityId, activityType, etc. are available.

let entityUrl;

// --- REFACTORED URL LOGIC ---
// Check for the special case: getting the activities of another Activity.
// For example, getting the 'Notes' (this.entity) of a 'Call' (entityType: 'Activity').
if (entityType === 'Activity' && this.entity === 'activity') {
    // Use the special endpoint format: /Activity/{sub-activity type}/{parent activity id}/activity
    entityUrl = `Activity/${activityType}/${entityId}/activity`;
} else {
    // Use the standard endpoint format for all other cases.
    const capitalizedEntityType = entityType.charAt(0).toUpperCase() + entityType.slice(1);
    entityUrl = `${capitalizedEntityType}/${entityId}/${this.entity}`;
}

// --- Improved Query String Combination ---
// This is a more robust way to combine query strings that avoids errors if one is missing.
const queryParts = [];
if (activityType) {
    queryParts.push(`activityType=${activityType}`);
}
if (query) {
    queryParts.push(query);
}
const combinedQuery = queryParts.join('&');

// The rest of your logic remains the same.
const result = await this.entityCacheService.getAll(undefined, entityUrl, page, limit, undefined, combinedQuery, undefined, this.entity);

// Ensure the 'entities' property is always an array.
if (result.entities === undefined) {
    result.entities = [];
}

return result;

let entityUrl = this.entity;
if (activityType && entityType && entityId) entityUrl = `activity/${activityType}/${entityType}/${entityId}`;

return this.entityCacheService.getCachedEntityValue(entityUrl, "entities");
